package com.finanscore.support.idempotency; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="processed_event",uniqueConstraints=@UniqueConstraint(name="uk_processed_event_consumer",columnNames={"event_id","consumer_name"})) public class ProcessedEventEntity { @Id @Column(name="processed_event_id") public UUID id; @Column(name="event_id",nullable=false,length=36) public String eventId; @Column(name="consumer_name",nullable=false,length=100) public String consumerName; @Column(name="processed_at",nullable=false) public Instant processedAt; }
